// Stack Manipulation (x86-64 Conventions)

// PUSH operation: Decrement %rsp, then store value
// (Standard operands are 64-bit, 8 bytes)
push %rax      // %rsp -= 8; [%rsp] = %rax

// POP operation: Load value, then increment %rsp
pop %rbx       // %rbx = [%rsp]; %rsp += 8

// Manual Stack Adjustment (e.g., reserving space)
sub $32, %rsp  // Reserve 32 bytes for local variables

// Accessing Local Variables (relative to %rsp)
movl $42, 8(%rsp) // 4th 8-byte slot (relative address)

// Cleaning up manual space
add $32, %rsp  // Restore %rsp

// Function Call Setup (Caller Side)
push %rdi      // Save caller-saved registers
call target_fn // Pushes current %rip onto stack
pop %rdi       // Restore caller-saved registers
